import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Handl Single-File Component (.hfc) Format","description":"","frontmatter":{"title":"Handl Single-File Component (`.hfc`) Format","type":"adr","date":"2026-10-28T00:00:00.000Z","status":"proposed","status_note":"Proposed."},"headers":[],"relativePath":"web/project/adrs/0116-handl-sfc-format.md","filePath":"vendored/web/project/adrs/0116-handl-sfc-format.md"}'),a={name:`web/project/adrs/0116-handl-sfc-format.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0116-handl-single-file-component-hfc-format" tabindex="-1">ADR-0116: Handl Single-File Component (<code>.hfc</code>) Format <a class="header-anchor" href="#adr-0116-handl-single-file-component-hfc-format" aria-label="Permalink to “ADR-0116: Handl Single-File Component (.hfc) Format”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>File layout.</strong> An <code>.hfc</code> file has three optional regions:</li><li><strong>Loader behavior.</strong> 1. Splits the file at region markers (<code>&lt;script&gt;</code>, <code>&lt;template&gt;</code>, <code>&lt;style&gt;</code>). 2. Parses <code>&lt;script&gt;</code> and <code>&lt;script setup&gt;</code> as a Handl module. 3. Parses <code>&lt;template&gt;</code> as a <code>view</code> block and runs the <code>component</code> transform from ADR-0117. 4. Carries <code>&lt;style&gt;</code> as data, rewriting selectors if <code>scoped</code> is present and adding the generated scope id to every host element in the <code>&lt;template&gt;</code>. 5. Emits a single Handl module plus a CSS string/artifact for the compile-to-JS backend.</li><li><strong><code>&lt;script&gt;</code> variants.</strong> available in the template. <code>state</code> declarations become reactive state. <code>props</code> (when exported as a record) becomes the component&#39;s props type. values and arrows are automatically exposed to the template and returned by the setup. This is the default for one-component-per-file files.</li><li><strong>Scoped styles.</strong> When <code>&lt;style scoped&gt;</code> is present, the loader:</li><li><strong>Slots.</strong> Slots are explicit <code>&lt;slot&gt;</code> elements. A default slot has no <code>name</code>; named slots use <code>name=&quot;...&quot;</code>. Scoped slots pass data back to the parent through a <code>let:</code> attribute on the slot and an <code>each</code> attribute for iteration. The lowering is the same Handl callback arrow mechanism described in ADR-0117.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p><a href="./0094-generic-ast-transform-engine.html">ADR-0094 — Generic AST Transform Engine</a> makes transforms first-class <code>Ast → Ast</code> passes. <a href="./0114-handl-compile-plugin-architecture.html">ADR-0114 — Handl Compile Plugin</a> is planned to lower Handl to JavaScript. <a href="./0115-handl-sdkgen-dts-js.html">ADR-0115 — <code>.d.ts</code> SDKgen</a> will generate Handl port/adapter pairs from NPM package declarations. <a href="./0117-handl-view-component-syntax.html">ADR-0117 — Handl View / JSX-like Component Syntax</a> defines the inline <code>view</code> syntax itself. The missing piece is a file format that bundles the view, the script, and the style into one source file, the way Vue SFCs do.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>One file per component, matching Vue/Astro/Svelte conventions.</li><li>The loader is a small pre-processor; the real syntax work is in ADR-0117.</li><li>The style step is not typechecked by Handl; it is emitted as data for the JS</li><li>Astro/Svelte/Vue/React can share the same <code>&lt;template&gt;</code> syntax and just need a</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (mechanism, tables, proofs, trade-offs): <a href="./../design/0116-handl-sfc-format.html"><code>design/0116-handl-sfc-format.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};